#!/usr/bin/env python3
"""
Guarded patch: recolor the Mining background from gold (#e8c98a, too
close to text/accent color ParchmentGold) to MiningStone (#7D8188) -
the slate gray-blue already established as Mining's own theme color
elsewhere in the app, and unused by any other skill's background.

Image-only change - no Kotlin code changes needed, just swaps the
drawable's bytes.
"""
import os
import base64

REPO_ROOT = "."
DRAWABLE_PATH = os.path.join(REPO_ROOT, "app/src/main/res/drawable/bg_mining_pickaxes.webp")

IMAGE_B64 = """"""

image_bytes = base64.b64decode(IMAGE_B64)
os.makedirs(os.path.dirname(DRAWABLE_PATH), exist_ok=True)
if os.path.exists(DRAWABLE_PATH) and os.path.getsize(DRAWABLE_PATH) == len(image_bytes):
    print(f"SKIP (already present, same size): {DRAWABLE_PATH}")
else:
    with open(DRAWABLE_PATH, "wb") as f:
        f.write(image_bytes)
    print(f"WROTE: {DRAWABLE_PATH} ({len(image_bytes)} bytes)")

print("Done.")
